#include <stdio.h>
int is_abundant(int x) {
    if (x <= 1) return 0;
    int sum = 1;
    for (int i = 2; i * i <= x; i++) {
        if (x % i == 0) {
            sum += i;
            if (i * i != x) sum += x / i;
        }
    }
    return sum > x;
}
int main() {
    int l, r; if (scanf("%d %d", &l, &r) != 2) return 0;
    int first = 1;
    for (int x = l; x <= r; x++) {
        if (is_abundant(x)) {
            if (!first) putchar(' ');
            printf("%d", x); first = 0;
        }
    }
    putchar('\n');
    return 0;
}

